"""HRSU-VideoBench comprehension: h2s-sewers / ceiling (generated by videobench.kaggle_task).

Scores how much of a verified explanation a viewer model gets from the video. Conditions:
none (no video: prior knowledge), visual (beat frames, muted, captions cropped away),
both (frames + narration). visual_lift = acc(visual) - acc(none).
"""
import random
import re

import kaggle_benchmarks as kbench
from kaggle_benchmarks.content_types import images

QUIZ = {
 "questions": [
  {
   "id": "q1",
   "beat": "step_1",
   "q": "In an oxygen-free sewer, which organisms produce hydrogen sulfide gas?",
   "answer": "Sulfate-reducing bacteria",
   "distractors": [
    "Nitrate-reducing bacteria",
    "Algae growing on the pipe walls",
    "Fungi that feed on concrete"
   ]
  },
  {
   "id": "q2",
   "beat": "step_1",
   "q": "What do these H2S-producing microbes use to break down organic matter?",
   "answer": "Sulfate, as their electron acceptor",
   "distractors": [
    "Oxygen dissolved in the sewage",
    "Nitrate added by the operator",
    "Calcium from the concrete"
   ]
  },
  {
   "id": "q3",
   "beat": "step_2",
   "q": "How does adding calcium nitrate cut H2S production?",
   "answer": "Nitrate-reducing bacteria outcompete the H2S producers for organic carbon",
   "distractors": [
    "The nitrate chemically neutralises H2S gas into water",
    "Calcium coats the concrete so H2S cannot touch it",
    "The nitrate kills every bacterium in the sewer"
   ]
  },
  {
   "id": "q4",
   "beat": "step_2",
   "q": "Why do nitrate-reducing bacteria win that competition?",
   "answer": "They have a higher affinity for nitrate than the H2S producers have for sulfate",
   "distractors": [
    "They consume sulfate faster than the H2S producers",
    "They are the only bacteria that survive without oxygen",
    "They release an acid that dissolves the H2S producers"
   ]
  },
  {
   "id": "q5",
   "beat": "step_3",
   "q": "How does hydrogen sulfide actually damage concrete pipes?",
   "answer": "It reacts with moisture to form sulfuric acid, which degrades the concrete",
   "distractors": [
    "It freezes inside the pores and cracks the concrete",
    "It raises the gas pressure until the pipe bursts",
    "It dissolves the steel reinforcement directly"
   ]
  },
  {
   "id": "q6",
   "beat": "step_3",
   "q": "At what point does calcium nitrate stop the corrosion?",
   "answer": "At the source: it stops H2S being produced, so no acid forms",
   "distractors": [
    "After the damage: it repairs acid-eaten concrete",
    "In the air: it dilutes the sulfuric acid",
    "On the surface: it seals the pipe wall"
   ]
  }
 ]
}
NARRATION = {
 "step_1": "To understand how corrosion is prevented, we must first look at how the corrosive gas is created. In an anaerobic environment\u2014which is an environment lacking free oxygen\u2014sulfate-reducing bacteria, or SRB, are microorganisms that produce hydrogen sulfide by processing sulfates. These SRB utilize sulfate as an electron acceptor, which is a molecule that accepts electrons during a redox reaction to enable energy production, to oxidize organic matter. This process releases H2S, the chemical formula for hydrogen sulfide gas, as a byproduct.",
 "step_2": "When a preferred chemical is introduced into this environment, the biological balance shifts. Calcium nitrate is a chemical salt providing nitrate ions to the wastewater stream. Nitrate-reducing bacteria, or NRB, are bacteria that prefer nitrate over sulfate as an electron acceptor. Because NRB possess a higher affinity for nitrate than SRB do for sulfate, NRB outcompete SRB for available organic carbon sources. As NRB outcompete SRB for carbon, the biological production of H2S is suppressed at the source.",
 "step_3": "Stopping the gas prevents physical damage to the pipes. Hydrogen sulfide gas normally reacts with moisture to form sulfuric acid, which is a highly corrosive mineral acid that degrades concrete infrastructure. By eliminating the H2S feedstock, the corrosive catalyst for concrete degradation is removed, stopping the process of decay."
}
GRIDS = {"step_1": "", "step_2": "", "step_3": ""}
REPS = 2
LETTERS = "ABCD"


def prompt_for(cond, q, options):
    opts = "\n".join(f"{LETTERS[i]}) {o}" for i, o in enumerate(options))
    if cond == "none":
        lead = "Answer this question about an industrial chemistry topic."
    elif cond == "visual":
        lead = ("The image is a grid of frames (read left-to-right, top-to-bottom) from one segment "
                "of a MUTED explainer video with no captions. Answer using what the visuals show; "
                "if they do not show it, give your best guess.")
    else:
        lead = ("The image is a grid of frames (read left-to-right, top-to-bottom) from one segment "
                "of an explainer video. The narrator says during it: \"" + NARRATION[q["beat"]]
                + "\" Answer using the video.")
    return (lead + "\n\nQuestion: " + q["q"] + "\n" + opts
            + "\n\nEnd your reply with a line of the form ANSWER: <letter>.")


def letter(reply):
    m = re.findall(r"ANSWER:\s*\(?([ABCD])\)?", reply or "", flags=re.I)
    return m[-1].upper() if m else ""


@kbench.task(name="hrsu-comp-h2s-sewers-ceiling",
             description="HRSU-VideoBench comprehension of h2s-sewers video 'ceiling'")
def comprehension(llm) -> dict:
    rng = random.Random(7)
    right = {"none": 0, "visual": 0, "both": 0}
    total = {"none": 0, "visual": 0, "both": 0}
    for q in QUIZ["questions"]:
        for rep in range(REPS):
            options = [q["answer"], *q["distractors"]]
            rng.shuffle(options)
            correct = LETTERS[options.index(q["answer"])]
            for cond in ("none", "visual", "both"):
                with kbench.chats.new(f"{q['id']}-{rep}-{cond}"):
                    kw = {} if cond == "none" else {
                        "image": images.from_base64(GRIDS[q["beat"]], format="jpeg")}
                    ans = letter(llm.prompt(prompt_for(cond, q, options), **kw))
                total[cond] += 1
                right[cond] += ans == correct
    acc = {c: round(right[c] / total[c], 3) for c in right}
    kbench.assertions.assert_true(acc["visual"] >= acc["none"],
                                  expectation=f"visuals add knowledge: {acc}")
    return {"acc_none": acc["none"], "acc_visual": acc["visual"], "acc_both": acc["both"],
            "visual_lift": round(acc["visual"] - acc["none"], 3)}


comprehension.run(kbench.llm)
